<?php

namespace Agent\AgentBundle\Repository;

/**
 * RoleAgentRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class RoleAgentRepository extends \Doctrine\ORM\EntityRepository
{
    public function triRole()
    {
        return $this->createQueryBuilder('r')
                    ->orderBy('r.libRole', 'DESC');
    }
}
